"""
readmes.py — the tables in checks/README.md and checks/<type>/README.md, generated from the test docstrings.

Each README has a hand-written introduction; the table between the markers

    <!-- tests:begin (generated by `dagtool readmes`; edit the test docstrings, not this table) -->
    <!-- tests:end -->

is rewritten from the files, so it always lists every test with what it checks and what a pass grants.
`dagtool readmes --check` (and tests/test_check_files.py) fail when a table is out of date.
"""

from __future__ import annotations

import re
from pathlib import Path

BEGIN = "<!-- tests:begin (generated by `dagtool readmes`; edit the test docstrings, not this table) -->"
END = "<!-- tests:end -->"
_BLOCK = re.compile(re.escape(BEGIN) + r".*?" + re.escape(END), re.S)


def _cell(text: str) -> str:
    flat = " ".join(text.split()).replace("|", "\\|")
    return flat[:1].upper() + flat[1:]


def type_table(kind: str) -> str:
    from checks._framework import discover, first_sentence
    rows = ["| Test | What it checks | A pass grants |", "|---|---|---|"]
    for tid, t in sorted(discover().items()):
        if t.type != kind:
            continue
        rows.append(f"| [`{tid}`]({t.name}.py) | {_cell(t.summary)} | {_cell(first_sentence(t.sections.get('Grants', '')))} |")
    return "\n".join(rows)


def index_table() -> str:
    from checks._framework import discover
    from checks._kinds import CHECK_KINDS
    tests = discover()
    rows = ["| Type | Question | Highest status | What it does | Tests |", "|---|---|---|---|---|"]
    for kind, meta in CHECK_KINDS.items():
        names = sorted(t.name for t in tests.values() if t.type == kind)
        listed = ", ".join(f"[`{n}`]({kind}/{n}.py)" for n in names)
        rows.append(f"| [{kind}]({kind}/README.md) | {meta.question} | {meta.ceiling} | {_cell(meta.summary)} | {listed} |")
    return "\n".join(rows)


def _fill(path: Path, table: str) -> str:
    text = path.read_text(encoding="utf-8") if path.exists() else ""
    block = f"{BEGIN}\n{table}\n{END}"
    if BEGIN in text and END in text:
        return _BLOCK.sub(lambda _m: block, text)
    return text.rstrip() + ("\n\n" if text.strip() else "") + block + "\n"


def readmes(root: Path, write: bool = True) -> list[Path]:
    """Regenerate every table; return the READMEs whose content changed (or would change)."""
    from checks._kinds import CHECK_KINDS
    checks = root / "checks"
    targets = [(checks / "README.md", index_table())]
    targets += [(checks / kind / "README.md", type_table(kind)) for kind in CHECK_KINDS]
    changed = []
    for path, table in targets:
        new = _fill(path, table)
        old = path.read_text(encoding="utf-8") if path.exists() else None
        if new != old:
            changed.append(path)
            if write:
                path.write_text(new, encoding="utf-8")
    return changed
